USE health_ai_platform;

-- ============================================================
-- Real policy content for the 5 core Nursing knowledge_docs
-- (v1/v2/v3 of each = 15 rows total), replacing the Faker
-- gibberish generated by generate_seed_data.py.
-- ============================================================

-- --- Case Management Acuity Scoring -----------------------------
UPDATE knowledge_docs SET content = 'Every open case management case is assigned an acuity level of LOW, MEDIUM, HIGH, or CRITICAL based on a structured scoring rubric covering: number of active chronic conditions (0-1 = low weight, 2-3 = medium, 4+ = high), recent inpatient or ED utilization (none in 90 days = low, one visit = medium, two or more = high), medication complexity (polypharmacy of 10+ active medications adds a full acuity tier), and documented social determinants of health barriers (housing instability, transportation access, caregiver support). CRITICAL acuity requires case manager contact within 1 business day of assignment; HIGH within 3 business days; MEDIUM and LOW within 5 and 10 business days respectively. Acuity is re-scored at every case manager contact, not just at intake, since a member''s situation can change quickly.'
WHERE dept_id = 3 AND title = 'Case Management Acuity Scoring';

UPDATE knowledge_docs SET content = 'Revision 2 adds a behavioral health co-occurrence multiplier: a documented behavioral health diagnosis alongside a physical health condition automatically raises acuity by one tier from the baseline score in v1, reflecting the well-established impact of comorbid behavioral health conditions on care complexity and outcomes. This revision also clarifies that acuity re-scoring at each contact (per v1) must be documented with the specific factors that changed, not just the new tier, so case managers reviewing the history can see the trajectory.'
WHERE dept_id = 3 AND title = 'Case Management Acuity Scoring v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a pediatric-specific scoring variant: the adult chronic-condition weighting in v1 does not map well to pediatric case management, so pediatric cases (members under 18) use a separate rubric weighted toward developmental milestones, caregiver capacity, and school-based support needs rather than medication count and inpatient utilization. This revision also introduces a "self-resolving" flag for cases where acuity has been LOW for three consecutive contacts, triggering a case-closure review rather than indefinite continued case management.'
WHERE dept_id = 3 AND title = 'Case Management Acuity Scoring v3';

-- --- Discharge Planning Checklist -----------------------------
UPDATE knowledge_docs SET content = 'Discharge planning must begin within 24 hours of inpatient admission notification, not at the point of discharge readiness. The core checklist covers: confirmed post-discharge living situation and caregiver availability, medication reconciliation against pre-admission medication list, scheduled follow-up appointment within 7 days for high-risk diagnoses (CHF, COPD, recent MI), durable medical equipment or home health referrals submitted before discharge day, and a documented "teach-back" confirmation that the member or caregiver can explain the discharge instructions in their own words. A discharge is not considered planning-complete until every checklist item is documented, even if the physical discharge occurs on schedule.'
WHERE dept_id = 3 AND title = 'Discharge Planning Checklist';

UPDATE knowledge_docs SET content = 'Revision 2 adds a 30-day readmission risk stratification step to the intake in v1: members are scored using validated criteria (e.g. LACE index components — length of stay, acuity of admission, comorbidities, ED visits in prior 6 months) and high-risk members receive a case manager phone call within 48 hours of discharge, not just the standard follow-up appointment scheduling. This revision also requires medication reconciliation to explicitly flag any new medication started during the inpatient stay for member/caregiver education, since these are the most common source of post-discharge confusion.'
WHERE dept_id = 3 AND title = 'Discharge Planning Checklist v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a skilled nursing facility (SNF) and rehab transfer variant of the checklist: for members discharged to a SNF rather than home, the "teach-back" and follow-up-appointment items in v1 are replaced with a warm handoff call to the receiving facility''s care coordinator and confirmation that the SNF has the complete discharge summary before transfer. This revision also adds an explicit equity checkpoint: DME/home health referrals must be confirmed as in-network and geographically accessible to the member''s discharge address, not just submitted.'
WHERE dept_id = 3 AND title = 'Discharge Planning Checklist v3';

-- --- Disease Management Enrollment Criteria -----------------------------
UPDATE knowledge_docs SET content = 'Members are eligible for disease management program enrollment based on a qualifying diagnosis (diabetes, CHF, COPD, or CKD stage 3+) combined with at least one utilization or risk indicator: an ED visit or inpatient admission related to the qualifying condition in the past 12 months, an A1C above 9.0 for diabetes enrollment specifically, or a case manager referral based on clinical judgment even absent the utilization criteria. Enrollment is voluntary — members may decline participation, and declining does not affect any other plan benefit. Programs run in structured phases: initial assessment call, individualized care plan development, and quarterly check-ins, with graduation criteria specific to each condition (e.g. two consecutive A1C readings under 8.0 for diabetes).'
WHERE dept_id = 3 AND title = 'Disease Management Enrollment Criteria';

UPDATE knowledge_docs SET content = 'Revision 2 lowers the diabetes A1C threshold in v1 from 9.0 to 8.5 for automatic enrollment eligibility, based on updated program outcomes data showing earlier intervention improved graduation rates. This revision also adds asthma as a fifth qualifying condition, using ED/urgent care visit frequency (2+ in 12 months) rather than a lab-value threshold as its utilization indicator, since asthma control is not well captured by a single lab marker the way diabetes is by A1C.'
WHERE dept_id = 3 AND title = 'Disease Management Enrollment Criteria v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a re-enrollment pathway: members who graduated from a disease management program per v1''s criteria but later show a recurrence of the utilization or risk indicators (e.g. a new ED visit related to the same condition) may be re-enrolled without needing to meet the full original qualifying criteria again, since a graduated member relapsing is treated as higher-priority than a first-time referral. This revision also adds a caregiver-inclusive enrollment option for pediatric and cognitively impaired adult members, where the caregiver — not the member — is the primary point of contact for program check-ins.'
WHERE dept_id = 3 AND title = 'Disease Management Enrollment Criteria v3';

-- --- Utilization Review Escalation SOP -----------------------------
UPDATE knowledge_docs SET content = 'Utilization review nurses conducting concurrent inpatient review must escalate to the UR physician advisor when: the requested length of stay exceeds the evidence-based guideline (e.g. InterQual/MCG criteria) by more than 2 days, the attending physician disagrees with a UR determination and requests physician-to-physician discussion, or the case involves a potential level-of-care mismatch (e.g. inpatient admission that may meet only observation criteria). Escalated cases must be reviewed by the physician advisor within 4 business hours during business days, or by the next business day for cases escalated after hours, since the member remains admitted throughout the review.'
WHERE dept_id = 3 AND title = 'Utilization Review Escalation SOP';

UPDATE knowledge_docs SET content = 'Revision 2 adds a same-day escalation requirement (down from 4 business hours in v1) for level-of-care mismatch cases specifically, since inpatient-vs-observation determinations have direct billing consequences for the member if not resolved before discharge. This revision also introduces a standing weekly case conference between UR nursing and the physician advisor team to review recent escalations in aggregate, intended to identify patterns (e.g. a specific attending physician or diagnosis category generating disproportionate escalations) rather than only handling escalations one at a time.'
WHERE dept_id = 3 AND title = 'Utilization Review Escalation SOP v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds an explicit non-retaliation and peer-to-peer standard: a physician-to-physician discussion requested under v1 must be scheduled without requiring the attending to first submit written justification, since requiring paperwork before a peer conversation was found to discourage legitimate escalation requests. This revision also clarifies that UR determinations are concurrent (during the stay) rather than retrospective by default — retrospective review of an already-completed stay follows a separate, less time-sensitive process outside this SOP.'
WHERE dept_id = 3 AND title = 'Utilization Review Escalation SOP v3';

-- --- Care Plan Documentation Standard -----------------------------
UPDATE knowledge_docs SET content = 'Every care plan must document, at minimum: the member''s stated goals in their own words (not just clinical goals set by the case manager), specific measurable interventions tied to each goal, a target timeframe for each intervention, and identified barriers to achieving the goal along with a mitigation approach. Care plans must be reviewed and updated at every case manager contact, not created once and left static — a care plan last updated more than 60 days ago on an open case is considered out of compliance. Member goals taking priority over clinical goals when the two conflict is intentional: care plans documenting only clinician-set goals without member input do not meet this standard.'
WHERE dept_id = 3 AND title = 'Care Plan Documentation Standard';

UPDATE knowledge_docs SET content = 'Revision 2 adds a structured barrier taxonomy to standardize the "identified barriers" field from v1 (financial, transportation, health literacy, caregiver capacity, housing, language access) so barrier data can be aggregated across the case management population to identify systemic gaps, rather than remaining as free text. This revision also shortens the out-of-compliance threshold from 60 to 45 days for CRITICAL and HIGH acuity cases specifically, reflecting that stale care plans are more consequential for higher-acuity members.'
WHERE dept_id = 3 AND title = 'Care Plan Documentation Standard v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds an interdisciplinary care team visibility requirement: care plans for members also engaged with disease management, utilization review, or behavioral health case management must be visible to those other teams (not siloed within case management alone), and any team updating a shared care plan must timestamp and attribute their specific update rather than overwriting the prior entry. This revision also formalizes member goal language in v1 as a required verbatim quote field, not a paraphrase, to preserve the member''s actual framing of their own priorities across care plan revisions.'
WHERE dept_id = 3 AND title = 'Care Plan Documentation Standard v3';
